def transform(grid):
    split = next(r for r, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:split], grid[split + 1:]
    width = len(grid[0])

    def background(region):
        counts = {}
        for row in region:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    bg_top = background(top)
    bg_bottom = background(bottom)
    return [
        [3 if top[r][c] != bg_top and bottom[r][c] != bg_bottom else 0
         for c in range(width)]
        for r in range(min(len(top), len(bottom)))
    ]
